#!/usr/bin/env bash
ssh -o BatchMode=yes host-machine 'export XDG_RUNTIME_DIR=/run/user/1000; export WAYLAND_DISPLAY=wayland-0; export DBUS_SESSION_BUS_ADDRESS=unix:path=/run/user/1000/bus; export XDG_SESSION_TYPE=wayland; pkill -9 -f "/home/trajan/Applications/T3-Code-fork|/tmp/.mount_T3|t3code" || true; nohup /home/trajan/Applications/T3-Code-fork-0.0.17-x86_64.AppImage --no-sandbox --ozone-platform=wayland >/tmp/t3-near-agentvm.log 2>&1 & sleep 8; AG=$(kdotool search --title "agent-vm \(1\)" 2>/dev/null | head -1); ID=$(kdotool search --class "place-companion" 2>/dev/null | head -1); echo ID=$ID AG=$AG; if [ -n "$AG" ] && [ -n "$ID" ]; then GX=$(kdotool getwindowgeometry "$AG" | awk "/Position:/ {split(\$2,a,\",\"); print int(a[1])}"); GY=$(kdotool getwindowgeometry "$AG" | awk "/Position:/ {split(\$2,a,\",\"); print int(a[2])}"); GW=$(kdotool getwindowgeometry "$AG" | awk "/Geometry:/ {split(\$2,a,\"x\"); print int(a[1])}"); kdotool windowactivate "$ID" >/dev/null 2>&1 || true; kdotool windowsize "$ID" 500 528 >/dev/null 2>&1 || true; NX=$((GX+GW+20)); NY=$GY; kdotool windowmove "$ID" "$NX" "$NY" >/dev/null 2>&1 || true; echo MOVED=$NX,$NY; fi; spectacle -b -n -f -o /tmp/t3-next-to-agentvm.png >/dev/null 2>&1 || true; ls -lh /tmp/t3-next-to-agentvm.png 2>/dev/null || true'